      if (ent === maEntityId) return false;
      const isMA = !!(this._knownMaEntities?.has(ent) || this._maEntityIds?.has(ent) ||
        (Array.isArray(this._config?.ma_entities) && this._config.ma_entities.includes(ent)));
      if (isMA) return false;
