    const _itemName   = item.name || item.title || '';
    const _itemArtist = (item.artists && item.artists[0]?.name) || '';
    const _nameId     = (_isTrackPlay && _itemName) ? (_itemName + (_itemArtist ? ' ' + _itemArtist : '')).trim() : null;

